def dailyTemperatures(temps):
    result = [0] * len(temps)
    stack = []  # indices

    for i in range(len(temps)):
        # Pop all colder days
        while stack and temps[i] > temps[stack[-1]]:
            idx = stack.pop()
            result[idx] = i - idx

        stack.append(i)

    return result
